package com.foodbridge.charity;
import org.springframework.core.io.FileSystemResource;import org.springframework.core.io.Resource;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import org.springframework.web.server.ResponseStatusException;import org.springframework.web.servlet.mvc.support.RedirectAttributes;import java.io.IOException;import java.nio.file.Files;import java.nio.file.Path;
@Controller @RequestMapping("/charity/documents") public class CharityDocumentController {
    private final CharityDocumentService service;private final CharityDocumentRepository repo;
    public CharityDocumentController(CharityDocumentService service,CharityDocumentRepository repo){this.service=service;this.repo=repo;}
    @GetMapping public String page(Authentication auth,Model model){model.addAttribute("documents",service.mine(auth.getName()));return "charity/documents";}
    @PostMapping public String upload(@RequestParam("file") MultipartFile file,Authentication auth,RedirectAttributes flash){try{service.upload(auth.getName(),file);flash.addFlashAttribute("success","Document uploaded for verification.");}catch(IllegalArgumentException|IOException e){flash.addFlashAttribute("error",e.getMessage()==null?"Upload failed.":e.getMessage());}return "redirect:/charity/documents";}
    @GetMapping("/{id}/download") public ResponseEntity<Resource> download(@PathVariable long id,Authentication auth){CharityDocument doc=repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));boolean admin=auth.getAuthorities().stream().anyMatch(a->a.getAuthority().equals("ROLE_ADMIN"));if(!admin&&!doc.getUploadedBy().equals(auth.getName()))throw new ResponseStatusException(HttpStatus.NOT_FOUND);try{Path p=service.resolvePrivate(doc.getStorageFilename());if(!Files.isRegularFile(p))throw new ResponseStatusException(HttpStatus.NOT_FOUND);Resource resource=new FileSystemResource(p);return ResponseEntity.ok().contentType(MediaType.parseMediaType(doc.getContentType())).header(HttpHeaders.CONTENT_DISPOSITION,ContentDisposition.attachment().filename(doc.getOriginalFilename()).build().toString()).body(resource);}catch(IOException|IllegalArgumentException e){throw new ResponseStatusException(HttpStatus.NOT_FOUND);}}
}
